pack.gossip = {
	[1103] = {
		{ f="1103-4ac3ad23", h="4ac3ad23", t="I'm a simple man who knows a few things about tailoring, but you need more assistance than I can provide. I have heard of a Night Elf who is quite an accomplished tailor. He resides in Stormwind, in the Magic District. ", d=13.280 },
		{ f="1103-b31c2daa", h="b31c2daa", t="I can tell that your wardrobe is in dire need of care.", d=3.640 },
		{ f="1103-ffa61dcd", h="ffa61dcd", t="So you would like to learn a few things? I would be happy to get you started!", d=4.680 },
	},
	[1154] = {
		{ f="1154-5fd240bc", h="5fd240bc", t="You've become quite the hunter, $n! Not only have you proven your skills, you also bested Daryl, which gets you extra points in my book!$B$BYou're welcome here any time.", d=13.320 },
	},
	[1156] = {
		{ f="1156-59a66cb6", h="59a66cb6", t="Welcome to the Farstrider Lodge, $n!", d=3.280 },
	},
	[1215] = {
		{ f="1215-ca38a19f", h="ca38a19f", t="You've made a good start, but you still have a great deal to learn, $n.", d=4.320 },
		{ f="1215-d0b84990", h="d0b84990", t="You've already learned everything I can teach you, $n. Talk to the night elf Lilyssia Nightbreeze in the Mage Quarter of Stormwind if you want to continue your studies. I hear she's a good teacher.", d=10.960 },
	},
	[3309] = {
		{ f="3309-2f8d506f", h="2f8d506f", t="Besides the Grunts outside, my brothers and I fought at the battle of Hyjal. Any who seek to steal from the bank must face us first.", d=9.680 },
		{ f="3309-6b36598f", h="6b36598f", t="I guarantee this bank's security with my own blood, is that good enough for you?", d=6.960 },
		{ f="3309-ae78a458", h="ae78a458", t="Would you rather trust your goods with a goblin?", d=3.640 },
	},
	[3318] = {
		{ f="3318-ae78a458", h="ae78a458", t="Would you rather trust your goods with a goblin?", d=3.920 },
	},
	[5943] = {
		{ f="5943-a28d29e1", h="a28d29e1", t="I can train you in First Aid techniques.", d=3.200 },
	},
	[6929] = {
		{ f="6929-7161de72", h="7161de72", t="If we are to make these new lands ours then we must have places to rest our battle weary bodies. Lay your axe by the fire and share the stories of your mighty battles.", d=15.800 },
	},
	[10042] = {
		{ f="10042-7c977ea2", h="7c977ea2", t="Grrr...", d=3.960 },
	},
	[10043] = {
		{ f="10043-8dddff62", h="8dddff62", t="I think Plugger filled one of his kegs too much.  It looks like it's about to blow!", d=5.760 },
		{ f="10043-e937cd6d", h="e937cd6d", t="Don't bother me while I'm partying...", d=4.400 },
	},
	[10086] = {
		{ f="10086-0e051c59", h="0e051c59", t="You've come for training in order to pass it on to your pets?", d=4.000 },
