	[11486] = {
		{ f="11486-ef2dd1b8", h="ef2dd1b8", t="For 10,000 years I have ruled this kingdom. In that time, I have heard many fascinating tales from those that would walk the hallowed grounds of the House of Shen'dralar.$B$BAs I am bound to this place, I often exchange stories with visitors. Do you have a story for me or perhaps you would like to hear a story?", d=21.470 },
	},
	[11491] = {
		{ f="11491-4faf9d1f", h="4faf9d1f", t="Thank you, mortal. There is but one service that I may offer to you before I return to the Dream.$B$BThe door to Zevrim's master, Alzzin, blocks your path. I shall act as your instrument of destruction. The door will be opened, I merely await your command.", d=15.280 },
		{ f="11491-d482a3a3", h="d482a3a3", t="Helpless... powerless... restore... must restore... Zevrim controls... end this torment...", d=7.360 },
	},
	[11536] = {
		{ f="11536-5cfd4d67", h="5cfd4d67", t="Certainly, $n.$B$BAdventurers that the Dawn views as honored must submit a combined total of 40 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 150 insignias.$B$BI must admit, the price is high even for those honored amongst the Dawn. ", d=23.630 },
		{ f="11536-7976f41a", h="7976f41a", t="Certainly, $n. You only need to tell me what reputation you would like to know about. ", d=5.800 },
		{ f="11536-895ae3cc", h="895ae3cc", t="Certainly, $n.$B$BAdventurers that the Dawn views as exalted must submit a combined total of 12 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 54 insignias.$B$BThose exalted in the eyes of the Dawn receive the greatest discounts. ", d=22.150 },
		{ f="11536-a6922fd2", h="a6922fd2", t="Certainly, $n.$B$BAdventurers that the Dawn views as revered must submit a combined total of 14 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 90 insignias.$B$BThose that are revered by the Dawn will find the cost of superior items quite reasonable! The cost for the more powerful items is still high. ", d=26.950 },
		{ f="11536-bc9ba896", h="bc9ba896", t="Greetings, $c.  I am Miranda Breechlock - one of but a few authorized equipment and materiel quartermasters for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Duke Zverenhoff.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you.", d=32.830 },
		{ f="11536-c95efe6a", h="c95efe6a", t="Certainly, $n.$B$BAdventurers that the Dawn views as friendly must submit a combined total of 60 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 220 insignias.$B$BI must admit, the price is quite high for adventurers not favored by the Dawn. ", d=22.190 },
	},
	[11548] = {
		{ f="11548-06b38db6", h="06b38db6", t="I've seen terrible things happen to the furbolg over the last few years--they were victims on many fronts. But it's unclear to me what's become of this tribe. Are they corrupted by the same plague that's touched Felwood? Or perhaps they are simply angry at what's happened to their once peaceful people and now seek to defend themselves. Either way, most of them appear hostile to those who come into the area.", d=29.150 },
		{ f="11548-0debc2eb", h="0debc2eb", t="Because you have aided me, I will tell you what I know of this land and of the things there are to see. My knowledge is not vast, but perhaps I can point out some things that might interest one such as yourself.", d=15.240 },
		{ f="11548-2ee418d2", h="2ee418d2", t="The blue dragons themselves aren't here, but followers of Malygos are. I do not know why, but I can tell you this: wherever the blue dragons are, expect to find arcane magic. I wouldn't be surprised if the dragonspawn are here protecting something... perhaps something the Highborne left behind.", d=21.800 },
		{ f="11548-517a6d40", h="517a6d40", t="A powerful human mage is rumored to live to the north; he keeps watch over the land for some unknown reason. I have not traveled there myself, but it is said that visitors are welcome and can even earn favor with him if they are willing to do errands for him.", d=17.280 },
		{ f="11548-628c29e8", h="628c29e8", t="Greetings, $c.$B$BThose Sentinels over there have allowed me to share their camp as long as I promise no trouble will follow--I am sure you can appreciate the need for diplomacy while here, yes?$B$BI am here investigating disturbances to the land, and since it aids their cause also, they have agreed that my presence here could only aid the tenuous alliance between all of Azeroth's races. If you wish to aid me, then I would appreciate it, but regardless, please try not to cause any trouble.", d=34.470 },
		{ f="11548-acbeb9d5", h="acbeb9d5", t="My knowledge of night elf lore is limited, but it is said long ago--back when the night elves still held sacred the art of arcane spell casting--that Azshara was the greatest of their kind. A beautiful woman they named queen. Sadly, it was her addiction to the arcane that would one day be the catalyst for the most devastating events in this world's history.", d=26.670 },
		{ f="11548-e1e14c50", h="e1e14c50", t="Once a great city of the night elves, the Highborne once ruled there, practicing great and powerful arcane magics. They are cursed now, haunting the lands, and their ruined city has been victimized by the Spitelash naga. I understand that the naga search the ruins for powerful Highborne artifacts.", d=20.560 },
	},
	[11554] = {
		{ f="11554-b55c64f7", h="b55c64f7", t="We are the last of the furbolg race... The Timbermaw tribe remains uncorrupted, yet we face the same hostility from outsiders; most believe that it is not possible... that there could actually be furbolg that escaped the corruption...$B$BAngry at those that strive to make enemies too quickly, my brethren now attack any that draw near; they trust no one.$B$BBut perhaps, if you strive to make your presence peaceful with them, they might look upon you as an ally.", d=28.270 },
	},
	[11555] = {
		{ f="11555-c1c3f615", h="c1c3f615", t="Yes, yes. I see you.$B$BBe on your way. You may have earned the trust of a few, but it will take more than that to prove it to me!", d=6.960 },
	},
	[11556] = {
		{ f="11556-21e024ed", h="21e024ed", t="The Winterfall furbolg that reside here in Winterspring were once our allies... But one day, that all changed.$B$BDriven by the strange demands of their high chief, they began to attack all others that they came in contact with, including our tribe. They keep to themselves now...", d=16.440 },
		{ f="11556-ffa625d1", h="ffa625d1", t="We Timbermaw can grant you safe passage through the hold, however, you must prove yourself worthy of our aid.", d=7.320 },
	},
	[11557] = {
		{ f="11557-14c8a268", h="14c8a268", t="If you prove that you are a true ally, I might consider training you...", d=4.840 },
	},
	[11558] = {
		{ f="11558-f0d1e4b1", h="f0d1e4b1", t="What do you seek, $c?", d=2.560 },
	},
	[11608] = {
		{ f="11608-54973df5", h="54973df5", t="Hello, $c. I've set up camp here at the Bulwark to make my preparations for my journey into the Plaguelands. I've heard rumor that a great human wizard took up residency in Hearthglen not terribly long ago. He was commissioned by the Scarlet Crusade to fashion their warriors and hunters new bows and guns. It's said that he completed a remarkable weapon before the Crusade killed him.$B$BI guess their mistrust of the arcane has grown.", d=29.270 },
	},
	[11609] = {
		{ f="11609-4e3fbf21", h="4e3fbf21", t="Greetings, $c. Don't have too much time to talk--I'm just using Chillwind as a camp to get some rest before heading to Hearthglen. I've heard word that before they went crazy, the Scarlet Crusade had a mage working for them who was trying to create powerful bows and guns for their soldiers. I'm not sure if he succeeded or not... the Crusade killed him before any of his finished product made it out. Maybe they killed him to keep it a secret... or maybe they distrust the arcane that much.", d=30.990 },
	},
	[11610] = {
		{ f="11610-5139f585", h="5139f585", t="He... hello, $n. Sorry, I'm recovering from my wounds.$B$BThose Scarlet Crusaders are tougher than I had given them credit for. They almost did me in.$B$BYou should be careful too. I'd hate to see them get the jump on you.", d=13.760 },
	},
	[11615] = {
		{ f="11615-061e5bb5", h="061e5bb5", t="My family worked  the Northridge Lumber Mill in what's now Western Plaguelands. They were dedicated to the Dumah family, and now the Scarlet Crusade have taken it over along with all of Hearthglen!$B$BI will not rest until those zealots are wiped from Azeroth.", d=21.720 },
	},
	[11616] = {
		{ f="11616-1fc62a48", h="1fc62a48", t="Long ago, before the last great war, my father ran the Northridge Lumber Mill. It was his life, and he was committed to it. Then the war came, and as much as it pained him, we had to flee to Stormwind.$B$BWe lost a number of friends and family in the those days, and it pains me to know that the Scarlet Crusade has taken the mill for their own ends.$B$BThat's why I've returned.", d=21.270 },
	},
	[11625] = {
		{ f="11625-9daa99a5", h="9daa99a5", t="Ah... a customer! Talk to my greatest invention, the Vendor-Tron 1000. He has all your needs... some of the rarest items you will ever find on the market anywhere in Kalimdor... not to mention that his programming will not allow any bargaining, so the price you see is the price you pay.", d=16.720 },
	},
	[11626] = {
		{ f="11626-78669df1", h="78669df1", t="This just happens to be your lucky day; I just completed Super-Seller 680's maintenance. There are tons of items for sell at great low-low prices. Go ahead and see for yourself... my brother Cork thinks his Vendor-Tron 1000 will out sell my bot.", d=13.920 },
	},
	[11627] = {
		{ f="11627-090a410e", h="090a410e", t="This kodo sure looks nothing like the beast I originally lured!  I wonder if the kombobulator can be used on me.", d=7.560 },
		{ f="11627-acf0ab05", h="acf0ab05", t="Why is it that small creatures such as goblins are always fascinated with larger creatures?", d=6.080 },
		{ f="11627-b8dda447", h="b8dda447", t="How do the goblins ever manage to secure packs to these beasts?  Kodos are ten times the size!", d=6.600 },
	},
	[11798] = {
		{ f="11798-1ba1d9c3", h="1ba1d9c3", t="You're not a druid!", d=2.560 },
		{ f="11798-26b6c691", h="26b6c691", t="If you're looking for a flight back to Rut'theran Village, then you should talk to my night elven counterpart, Silva Fil'naveth.", d=9.280 },
		{ f="11798-48369fd3", h="48369fd3", t="The waters of Westfall are where you must search, due west-northwest of where the Gold Coast Quarry meets with the shore.  An anchor shows where a boat has sunk beyond it, deep within the water.  The underwater pressure is fierce here; swimming too far will crush even the mightiest swimmer from fatigue.  $B$BLook for a natural formation to aid you, $n - a bubbly fissure is near here, offering deep-water swimmers a chance for renewed breath. ", d=28.670 },
		{ f="11798-4ac22243", h="4ac22243", t="In the Silverpine Forest along the edges of the North Tide's Run, a derelict boat rests on the shore.  Out to the west of this lies what you seek; swim too far and the ocean will crush you from fatigue.  It resides on the ocean floor in a lockbox, waiting for you to claim it.$B$BYou'll be hard pressed to survive a dive to such depths without aid, so take heart; a bubbly fissure offers renewed breath to divers seeking this half of the pendant.  Use it wisely.", d=31.430 },
		{ f="11798-a2b097f2", h="a2b097f2", t="Would you like a flight to Thunder Bluff, courtesy of the Cenarion Circle?", d=5.640 },
	},
	[11799] = {
		{ f="11799-992f6a78", h="992f6a78", t="The Shrine of Remulos is a sacred place for us in the Cenarion Circle here in Moonglade... so please conduct yourself in a manner befitting a visitor.$B$BA visitor who doesn't want my scimitar buried in them, that is.", d=14.760 },
	},
	[11800] = {
		{ f="11800-1ba1d9c3", h="1ba1d9c3", t="You're not a druid!", d=1.920 },
		{ f="11800-2051e10a", h="2051e10a", t="Would you like a flight to Rut'theran Village, courtesy of the Cenarion Circle?", d=6.200 },
		{ f="11800-d1f50557", h="d1f50557", t="In the northeastern Barrens lies a pool of water sickened by pollution.  The locals call it the Sludge Fen; the Venture Company has turned the once crystal-blue waters into a mire of industrial byproducts and waste.  In the heart of this fen lies what you seek, $n.$B$BBe warned - the Venture Company does not tolerate trespassers, and they consider anyone who does not work for them as such.  You'll especially be a target as a protector of nature, something they vehemently oppose.", d=36.790 },
		{ f="11800-d5d73f6c", h="d5d73f6c", t="In the northern part of Darkshore runs the Cliffspring River, flowing down from the lands now known as Felwood.  As the river flows out and empties out into the Mist's Edge, travel north to where the deepest parts of the ocean begin.  A stone formation that some call the Stone Claw due to its shape is where you may find what you seek.$B$BBe warned - threshers gather by the Stone Claw, and will attack those who trespass on their territory.", d=33.190 },
		{ f="11800-fd86ada1", h="fd86ada1", t="If you're looking for a flight back to Thunder Bluff, then you should talk to my tauren counterpart, Bunthen Plainswind.", d=9.920 },
	},
	[11801] = {
		{ f="11801-56e4b018", h="56e4b018", t="I... cannot begin to imagine, $n.  All I know is that I am not going to allow it to happen.  It will be destroyed - if not for our continued safety from demonic taint, then for the memory of Millicent Serene... Milli...$B$BThis, my friend, this is where I hope you will come in.", d=19.560 },
		{ f="11801-8d7dff6e", h="8d7dff6e", t="In ages past, Eldre'Thalas was a nexus of magical power, and those who dwelt within its hallowed halls wielded immense power.  One such night elf was Millicent Serene - a naturalist who willed the power of nature itself into potent artifacts she forged.$B$BThe Fruit of Fertility was her crowning achievement... she used a specially prepared moonwell to grow an exotic and vibrant vine that was imbued with an aura of protection and growth.  All of Eldre'Thalas flourished from its existence.", d=34.270 },
		{ f="11801-94d18cfb", h="94d18cfb", t="Aye, but I know it by its true name - Eldre'Thalas.  It was a bastion of magical power for the night elves many, many years ago.$B$BYou know of Eldre'Thalas, young one?  One might say that is coincidental to my current plight... but I am one not to believe in coincidence.", d=18.200 },
		{ f="11801-a29aa29d", h="a29aa29d", t="Alas, it always seems like it does.  I - as did the rest of the Cenarion Circle - had assumed that Milli's creation was destroyed during the War of the Ancients.  This, as I have come to learn, is far from correct.$B$BThe Fruit of Fertility survived... though now it is known as the Felvine.  It is being corrupted by the demonic lord of that section of Eldre'Thalas, Alzzin the Wildshaper.", d=25.790 },
		{ f="11801-bbb95b77", h="bbb95b77", t="Don't listen to the hearts of the world - the answer lies within.  You know the truth.", d=4.840 },
		{ f="11801-c9fa662a", h="c9fa662a", t="Agents of the Cenarion Circle have uncovered disturbing information pertaining to the current situation in Eldre'Thalas.  I am at an impasse as to what to do about it, and I will no doubt soon seek the aid of able bodied beings capable of handling themselves in a fight.$B$BTo properly take action in Eldre'Thalas, however, is to understand the lore of an object known as the Fruit of Fertility.", d=24.710 },
	},
	[11802] = {
		{ f="11802-ef8483c2", h="ef8483c2", t="Greetings, $c.  You are welcome in Nighthaven, as well as all of Moonglade.  The Cenarion Circle welcomes all beings who respect the authority and command of nature.$B$BWhile you are here, please be sure to preserve the balance in all things.  Disturbances are not welcome here, and our wardens are trained to cease all hostilities without question.", d=21.270 },
	},
	[11811] = {
		{ f="11811-47b6c897", h="47b6c897", t="<Narain holds an unopened envelope to his forehead.>$B$BWhat is... Mmmm... Velvet!$B$BAm I right?", d=3.080 },
		{ f="11811-a2b3f45f", h="a2b3f45f", t="Don't tell me! Shhh! You are here about the Ashbringer?!? Yes... Yes... No! My bad.$B$BWhat can I help you with, $r?", d=8.320 },
		{ f="11811-ea7ea300", h="ea7ea300", t="Narain Soothfancy, at your service! Retired engineer and master soothsayer! I can tell your future before it even happens!", d=8.680 },
		{ f="11811-f82e07d8", h="f82e07d8", t="It... It's foggy, $N. I can't see anything! Wait... Wait a minute. I see... I see Doctor Weavil's hideout. It... YES! I believe he is holding a chapter of the book!$B$BLet me see if I can zoom this thing out to get a better vantage point.$B$B<Narain appears to be going cross-eyed.>$B$BAlcaz Island! That devious bastard is on Alcaz Island!", d=20.320 },
	},
	[11833] = {
		{ f="11833-eb2e4319", h="eb2e4319", t="Well met, $c. You may speak to me unless you have direct business with my mistress Magatha.  I deal with most of her tasks for her so she can concentrate on more important matters. Perhaps there are some things we could discuss before you seek audience with her?", d=16.080 },
	},
	[11835] = {
		{ f="11835-0f923099", h="0f923099", t="Hello, $N.", d=1.760 },
	},
	[11860] = {
		{ f="11860-ae16ea2b", h="ae16ea2b", t="I am afraid that I am no longer gentle or humble. Age and countless battles have hardened my skin and soul. Perhaps that is why Cairne assigned me to Sun Rock Retreat... the gentle winds and warm sun does ease the pain.", d=18.280 },
	},
	[11861] = {
		{ f="11861-2ff59fb5", h="2ff59fb5", t="Stonetalon Mountain has many perilous caves through out this region.  Exploring these caves can hold many adventures for those willing to risk life for glory.$B$B$C, perhaps you seek riches that only following your heart and soul can garnish.", d=18.080 },
	},
	[11865] = {
		{ f="11865-b5f74fe6", h="b5f74fe6", t="Bixi Wobblebonk, the gnome weapon master, is wandering about in this shop.  She can teach crossbow, daggers and throwing weapons.  Woo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.  Ilyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons.", d=34.630 },
	},
	[11866] = {
		{ f="11866-7e580c62", h="7e580c62", t="Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.  Bixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.  Woo Ping, the human weapon master at Weller's Arsenal in Stormwind, teaches crossbow, daggers, one and two-handed swords, polearms, and staff.", d=35.950 },
		{ f="11866-f3b1497b", h="f3b1497b", t="The grace with which I fight is not something I can teach you, but I can teach you the use of various weapons.", d=8.360 },
	},
	[11867] = {
		{ f="11867-3f5ede7c", h="3f5ede7c", t="Have you come seeking training in the ways of armed combat?", d=3.760 },
		{ f="11867-d85affd4", h="d85affd4", t="Buliwyf, the dwarven weapon master at the Timberline Arms in Ironforge, teaches fist weapons, guns, one and two-handed axes and one and two-handed maces.  Bixi Wobblebonk, the gnome weapon master at the Timberline Arms in Ironforge, teaches crossbow, daggers and throwing weapons.  Ilyenia Moonfire, the night elf weapon master, resides at the Warrior's Terrace in Darnassus where she teaches bow, daggers, fist weapons, staff and throwing weapons.", d=26.670 },
	},
	[11868] = {
		{ f="11868-48da0bbc", h="48da0bbc", t="Here to learn how to wield a new weapon, or just to waste my time?", d=5.160 },
		{ f="11868-a545ee73", h="a545ee73", t="Ansekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He can train one and two-handed maces, staves and guns.  Hanashi, standing next to me here, can instruct in the use of bows, one and two-handed axes, staves and all manner of thrown weapons.  Archibald, the undead weapon master in the War Quarter of the Undercity, can teach the use of crossbows, daggers, one and two-handed swords and polearms.", d=32.670 },
	},
	[11869] = {
		{ f="11869-49ff395c", h="49ff395c", t="I would be honored to train you in the use of the weapons that I have mastered should you have the ability to learn within you.", d=7.280 },
		{ f="11869-b4d7a83a", h="b4d7a83a", t="Sayoc is the orc weapon master and is located in Orgrimmar's Valley of Honor.  He instructs in the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.  Hanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can teach the use of bows, one and two-handed axes, staves and thrown weapons.  Archibald, the undead weapon master in the War Quarter of the Undercity, can train the use of crossbows, daggers, one and two-handed swords and polearms. ", d=34.540 },
	},
	[11870] = {
		{ f="11870-3a5c3d7e", h="3a5c3d7e", t="I suppose you are here to be trained in the use of a new weapon?  Make it fast, I'm very busy!", d=5.760 },
		{ f="11870-a5868f28", h="a5868f28", t="Sayoc is the orc weapon master.  He is located in Orgrimmar's Valley of Honor.  He can train the use of bows, daggers, fist weapons, one and two-handed axes and thrown weapons.  Hanashi, the troll weapon master in the Valley of Honor of Orgrimmar, can instruct in the use of bows, one and two-handed axes, staves and all thrown weapons.  Ansekhwa, the tauren weapon master, is on Thunder Bluff's lower rise.  He teaches the use of one and two-handed maces, staves and guns. ", d=33.910 },
	},
	[11872] = {
		{ f="11872-a76f6bcc", h="a76f6bcc", t="These are dangerous times, adventurer. Walk lightly.", d=4.520 },
		{ f="11872-fc3dd340", h="fc3dd340", t="Do you require an illusion?$B$BShould your illusion falter in the midst of your quest, return to me and I shall reapply the guise.$B$BShould you fail in your endeavors, do not give up! Return to me. I shall assist you until you have completed your objectives.", d=17.360 },
	},
	[11878] = {
		{ f="11878-b33292cd", h="b33292cd", t="No doubt you are another inept simpleton sent from the Dark Lady to train under her champion.$B$B<Nathanos sighs.>$B$BI've sent every one of you back to her in pieces, I don't see why it will be any different this time.$B$BMine, however, is not to question why, but instead to do as the Dark Lady bids.", d=17.280 },
	},
	[11899] = {
		{ f="11899-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=3.520 },
	},
	[11900] = {
		{ f="11900-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.280 },
	},
	[11901] = {
		{ f="11901-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.040 },
	},
	[11939] = {
		{ f="11939-83dc2991", h="83dc2991", t="If you're looking for information that the Cenarion Circle might have archived somewhere, then I'm the one to talk to.  Then again, you need to know what information you're looking for first before I can really help you.$B$BSee how that works?  Brilliant!", d=12.760 },
	},
	[11956] = {
		{ f="11956-0359e6b8", h="0359e6b8", t="Strength of the heart is what gives you the resolve to take action... action that is rooted in intents that are pure and forthright.  To keep the balance is not to be complacent or banal.$B$BYou must show resolve for that which you believe in, and you must be willing to fight for it.  The mother bear shows endless conviction in protecting her young, as does an elder bear protecting his den.  It is this resolve, this strength of heart, which you must come to know if you are to master the way of the Claw.", d=28.110 },
		{ f="11956-59f9a1e9", h="59f9a1e9", t="It remains to be seen if you are ready, young one.  Even the wisest and oldest of druids are never truly ready when their ultimate time of testing comes.$B$BYou have heard my words, and now you must move on.  Heed what I have taught you.  There will be a time when you will have your strength tested.  You must face your foe as the bear would - with strength of body and with strength of heart.  Learn from the fight, young one.  Go... with my blessings.", d=24.790 },
		{ f="11956-86efb831", h="86efb831", t="The bear spirit looks upon you with a calm and peaceful gaze.  You hear a voice speak to you as though it was coming from the bear, but the creature makes no indication that it is speaking.$B$B\"Greetings, my young friend.  If you have come to me seeking guidance, then perhaps I can help you find what you seek.\"", d=16.510 },
		{ f="11956-bab3e0cd", h="bab3e0cd", t="I represent the strength which bolsters you as a young druid.  You have come to me to learn this strength, young one, and I will teach this to you.  I will teach you all that is the spirit bear, provided you will listen and understand.$B$BIn order to know what it means to draw upon my spirit, you need to understand the importance of the strength of the body, as well as the strength of the heart.", d=22.310 },
		{ f="11956-cbd3ea7f", h="cbd3ea7f", t="The bear looks at you calmy and patiently, but says nothing.", d=3.600 },
		{ f="11956-d6a631ca", h="d6a631ca", t="Strength of the body is the power and swiftness of action.  You must keep yourself fit at all times, both physically and mentally.  The bear's girth highlights its strength, as it is a ferocious foe in combat.  The bear's girth, however, belies its lithe agility and sharp mind.  These are surprises you will use to your advantage.$B$BYou must rely on the strength of the bear's body in order to master the way of the Claw.", d=24.550 },
	},
	[12018] = {
		{ f="12018-6a1f358f", h="6a1f358f", t="The Firelord and his brethren once held sway over this entire world, mortal. As a servant of the Old Gods, he fought against the Titans for domination of this planet. The victorious Titans banished my master and his brethren to the Elemental Plane - there to remain imprisoned until the end of time.", d=16.480 },
		{ f="12018-aed2736f", h="aed2736f", t="A mere three hundred years ago, a reckless dwarf named Thaurissan summoned the master from his fiery realm. His return to this paltry world devastated the surrounding lands and created this volcanic Core. Mighty Ragnaros has slept under this mountain ever since.  ", d=17.000 },
		{ f="12018-ecff1016", h="ecff1016", t="We, his sworn servants, do his bidding and enforce his iron-rule. Cut off from the energies of his fiery realm, Ragnaros is but a shadow of his true self. However, he has more than enough strength to be your end.       ", d=13.200 },
	},
	[12031] = {
		{ f="12031-eab06e19", h="eab06e19", t="I should find some hired help; I don't like sitting here all day selling fish supplies. I'd much rather go fishing, and then sell supplies.", d=13.120 },
	},
	[12032] = {
		{ f="12032-279d82d3", h="279d82d3", t="Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of \"The Bass and You\".  That is sure to help you increase your skill.", d=15.640 },
		{ f="12032-837eac47", h="837eac47", t="You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently.", d=9.160 },
		{ f="12032-c2467ddc", h="c2467ddc", t="I can teach you fishing skills.", d=3.440 },
	},
	[12042] = {
		{ f="12042-cf843c85", h="cf843c85", t="Even within cold, stone walls such as the ones that shelter this town, one may find tranquility and peace.  In fact, you may find them everywhere you are... simply look inside yourself for such balance.", d=12.240 },
	},
	[12136] = {
		{ f="12136-866b6683", h="866b6683", t="Hey there cutie, you looking for a ride to Grom'gol? I hear it gets mighty steamy down in those jungles, maybe I could join you for a short vacation, show you a real jungle cat.", d=11.880 },
	},
	[12137] = {
		{ f="12137-c087faab", h="c087faab", t="Slip a little coin into the boss's hand and look what it gets ya. I love my job. Though, if I could find a way to get that little firecracker Snurk reassigned to this port....well, I can't imagine it any better. But I'm betting that you aren't here about my business practices. You're looking for the Zeppelin to Undercity, am I right? Well that's great, because it docks right here behind me. Oh and hey, if you see Snurk, put a good word in for me, would ya?", d=26.230 },
	},
	[12144] = {
		{ f="12144-8e6ce242", h="8e6ce242", t="The spirit looks intently into your eyes and grasps your hand.  You feel a warmth shoot through your body, almost knocking you to your knees.$B$BAs the warmth passes, you feel the slight presence of an ursine spirit within your being... bolstering your resolve.", d=13.000 },
		{ f="12144-ac452739", h="ac452739", t="The slain spirit of Lunaclaw stares at you intently, as though wanting something from you.", d=4.920 },
	},
	[12196] = {
		{ f="12196-03ca5480", h="03ca5480", t="Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory.   ", d=34.190 },
		{ f="12196-174473b0", h="174473b0", t="Recently, a night elf druid named Naralex discovered a network of underground caverns within the heart of the Barrens. Believing he could use the caverns' springs to restore lushness to the Barrens, the druid began siphoning the energies of the fabled Emerald Dream. His vision somehow became a nightmare, however, and soon the Wailing Caverns changed into a den of vicious, deadly predators. It is said that Naralex still resides somewhere inside the labyrinth, trapped beyond the edges of the Emerald Dream.  ", d=42.750 },
		{ f="12196-17e9d243", h="17e9d243", t="Uldaman is an ancient Titan vault that has laid buried within the earth since the world's creation. Dwarven excavations of the city have recently released the Titans' first failed creations: the troggs. Legends say that when the Titans deemed the trogg experiment a failure they tried again, resulting in the creation of the dwarven race. These secrets are recorded on the fabled Discs of Norgannon - massive artifacts that lie at the bottom of the ancient city, protected by giant constructs of living stone.  ", d=44.620 },
		{ f="12196-19490f29", h="19490f29", t="Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. ", d=46.150 },
		{ f="12196-19cbe7de", h="19cbe7de", t="When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande.", d=23.400 },
		{ f="12196-1a6e2552", h="1a6e2552", t="This sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called Sul'thraze the Lasher, a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls. ", d=37.470 },
		{ f="12196-22aa3fe4", h="22aa3fe4", t="Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road.", d=8.520 },
		{ f="12196-2e88eda5", h="2e88eda5", t="Frustrated by the Dalaran wizards' lack of progress against the undead during the Third War, the Archmage Arugal elected to summon the extra-dimensional worgen to bolster his side's diminishing ranks. The wolf-men slaughtered the Scourge, then quickly turned on the wizards themselves and laid siege to the keep of the noble, Baron Silverlaine. The fort quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'.  ", d=42.780 },
		{ f="12196-3141b27b", h="3141b27b", t="Crafted from the same vines as Razorfen Kraul, Razorfen Downs is the traditional capital city of the quilboar race. The sprawling, thorn-ridden labyrinth houses a veritable army of loyal quilboar as well as their high priests - the Death's Head tribe. Recently, however, a looming shadow has fallen over the crude den. Agents of the undead Scourge - led by the lich, Amnennar the Coldbringer - have taken control over the quilboar race and turned the maze of thorns into a bastion of undead might.   ", d=42.790 },
		{ f="12196-330cd2db", h="330cd2db", t="The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself.  ", d=43.070 },
		{ f="12196-33439fd8", h="33439fd8", t="Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons. ", d=45.030 },
		{ f="12196-342c02c0", h="342c02c0", t="The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free.  ", d=33.430 },
		{ f="12196-4a0923b3", h="4a0923b3", t="Are you interested in exploring one of these dungeons?", d=5.080 },
		{ f="12196-4a6950fb", h="4a6950fb", t="The ruins of Dire Maul stand in central Ferelas.", d=5.400 },
		{ f="12196-4f48ef1f", h="4f48ef1f", t="Situated along the Zoram Strand of Ashenvale, Blackfathom Deeps was once a glorious temple dedicated to the night elves' moon-goddess Elune. However, the great Sundering shattered the temple - sinking it beneath the waves of the Veiled Sea. There it remained untouched - until, drawn by its ancient power - the naga and satyr emerged to plumb its secrets. Legends hold that the ancient beast, Aku'mai, has taken up residence within the temple's ruins.  ", d=40.030 },
		{ f="12196-581034a1", h="581034a1", t="The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain. ", d=42.790 },
		{ f="12196-5dc31760", h="5dc31760", t="During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose. ", d=46.670 },
		{ f="12196-5eccd4fa", h="5eccd4fa", t="The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows.", d=8.080 },
		{ f="12196-5ff7a251", h="5ff7a251", t="Scarlet Monastery lies in the hills northeast of Tirisfal Glades.", d=6.560 },
		{ f="12196-66f64f6e", h="66f64f6e", t="Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road.", d=8.520 },
		{ f="12196-69040db4", h="69040db4", t="Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they'll give you a gift of friendship.", d=21.480 },
		{ f="12196-6a089d41", h="6a089d41", t="The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood.", d=7.760 },
		{ f="12196-70185dce", h="70185dce", t="Uldaman can be found at the very northern end of the Badlands.", d=4.920 },
		{ f="12196-7161de72", h="7161de72", t="If we are to make these new lands ours then we must have places to rest our battle weary bodies. Lay your axe by the fire and share the stories of your mighty battles.", d=15.800 },
		{ f="12196-7b1bcef4", h="7b1bcef4", t="The Deadmines can be found beneath Moonbrook in the south of Westfall.", d=6.160 },
		{ f="12196-7de88db1", h="7de88db1", t="Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city.  ", d=39.070 },
		{ f="12196-864c5566", h="864c5566", t="The Wailing Caverns has its entrance at the Lushwater Oasis southwest of Crossroads in the Barrens.   ", d=8.760 },
	},
}
